    function testFuzz_property(uint256 amount, address attacker) public {
        vm.assume(amount > 0);
        vm.assume(attacker != address(0) && attacker != address(c));
        vm.deal(attacker, amount);
        vm.prank(attacker);
        (bool sent,) = address(c).call{value: amount}("");
        require(sent, "funding failed");
        uint256 contractBalanceBefore = address(c).balance;
        try c.withdraw() {
            uint256 contractBalanceAfter = address(c).balance;
            assertTrue(contractBalanceAfter == contractBalanceBefore - amount);
        } catch {
            assertTrue(true);
        }
    }
}
